 // Fake folder: {name: sizeInBytes | {subfolder}}, with the File System Access methods the app uses.
 function fakeDir(tree,name='Pasta'){return {kind:'directory',name,async queryPermission(){return 'granted'},async requestPermission(){return 'granted'},async isSameEntry(o){return o===this},
   async *entries(){for(const [n,v] of Object.entries(tree))yield [n,typeof v==='number'?fakeFileHandle(n,v):fakeDir(v,n)];},
   async getDirectoryHandle(n){if(typeof tree[n]!=='object')throw Error('NotFound');return fakeDir(tree[n],n)},
   async getFileHandle(n){if(typeof tree[n]!=='number')throw Error('NotFound');return fakeFileHandle(n,tree[n])}};}
 function fakeFileHandle(n,size){return {kind:'file',name:n,async getFile(){return new File([new Uint8Array(size)],n)}};}
